import{_ as e,c as i,o as r,ag as t}from"./chunks/framework.DfL_BkQ-.js";const d=JSON.parse('{"title":"隐私选项","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy-choices.md","filePath":"zh-CN/guide/privacy-choices.md","lastUpdated":1794112334000}'),s={name:"zh-CN/guide/privacy-choices.md"};function o(c,a,l,h,n,p){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="隐私选项" tabindex="-1">隐私选项 <a class="header-anchor" href="#隐私选项" aria-label="Permalink to &quot;隐私选项&quot;">​</a></h1><p>本页说明如何向 Nicasa 提交隐私请求，以及你可以预期的处理方式。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>你可以使用本页请求查阅个人数据、请求删除、请求数据可携带，或选择退出某些数据使用（例如在适用情况下的「请勿出售」请求）。</p><p>说明：Nicasa 目前不收集也不存储个人数据（见隐私政策）。如果你确信我们持有关于你的个人数据，请提交请求，我们会展开调查。</p><h2 id="如何提交请求" tabindex="-1">如何提交请求 <a class="header-anchor" href="#如何提交请求" aria-label="Permalink to &quot;如何提交请求&quot;">​</a></h2><p>提交请求时请提供以下信息，以便我们高效处理：</p><ul><li>你的姓名</li><li>联系邮箱</li><li>请求说明（查阅、删除、可携带或退出）</li><li>任何有助于我们定位记录的信息（例如支持工单编号）</li></ul><p>请将请求发送至以下任一渠道：</p><ul><li>邮箱：nicasa@w3cub.com</li><li>提交隐私 issue：<a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li></ul><h2 id="响应时间" tabindex="-1">响应时间 <a class="header-anchor" href="#响应时间" aria-label="Permalink to &quot;响应时间&quot;">​</a></h2><p>我们力求在 30 天内确认并回应有效请求。如需要更多时间，我们会通知你并给出预计时间。</p><h2 id="如果我们未持有个人数据" tabindex="-1">如果我们未持有个人数据 <a class="header-anchor" href="#如果我们未持有个人数据" aria-label="Permalink to &quot;如果我们未持有个人数据&quot;">​</a></h2><p>由于 Nicasa 的设计是在本地处理图片而不收集用户数据，许多请求会以「未持有任何个人数据」的确认结案。如果你能提供个人数据曾被收集的证据，我们会展开调查并采取适当措施。</p><h2 id="请勿出售-选择退出" tabindex="-1">请勿出售 / 选择退出 <a class="header-anchor" href="#请勿出售-选择退出" aria-label="Permalink to &quot;请勿出售 / 选择退出&quot;">​</a></h2><p>如果你正在行使某一司法辖区的权利（例如依据 CCPA/CPRA）要求退出数据出售，并且你确信我们曾出售你的个人数据，请在请求中说明具体情况。如果我们并未出售个人数据，会在答复中予以确认。</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>如对本流程有疑问，请联系 <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a>，或在 <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a> 提交 issue。</p>',18)])])}const b=e(s,[["render",o]]);export{d as __pageData,b as default};
